import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Tabs, Tab, Input, Link, Card, CardBody, CardHeader, user, Image } from "@heroui/react";
import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import { useStateContext } from "../../contexts/ContextProvider";
import LocalParkingIcon from '@mui/icons-material/LocalParking';
import NotInterestedIcon from '@mui/icons-material/NotInterested';
import WifiIcon from '@mui/icons-material/Wifi';
import SingleBedIcon from '@mui/icons-material/SingleBed';
import KingBedIcon from '@mui/icons-material/KingBed';
import { BreakfastDining } from "@mui/icons-material";
import { Carousel } from "antd";



export default function RoomDetailsModal({ showRoomDetailsModal, setshowRoomDetailsModal, selectedRoomToView }) {
    const [existing, setExisting] = useState()
    const { } = useStateContext()
    const [selectedItems, setselectedItems] = useState(localStorage.getItem("selectedItems") ? JSON.parse(localStorage.getItem("selectedItems")) : [])

    // useEffect(() => {
    //     if (selectedFoodItem && selectedItems.length)
    //         setExisting(selectedItems.length && selectedItems.find(x => x.id === selectedRoomToView.id));
    // }, [selectedFoodItem, selectedItems])




    return (
        <>

            <Modal
                isOpen={showRoomDetailsModal}
                placement="top"

            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />


                            <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">ROOM : {selectedRoomToView.title}</ModalHeader>
                            <ModalBody>
                                <Card shadow="sm" >
                                    <CardBody className="overflow-visible p-0">
                                        <Carousel autoplay>

                                            {
                                                selectedRoomToView.room_images && selectedRoomToView.room_images.length && selectedRoomToView.room_images.map(image => <Image
                                                    shadow="sm"
                                                    radius="md"
                                                    width="100%"
                                                    alt={selectedRoomToView.title}
                                                    className="w-full object-cover h-[200px]"
                                                    src={image.image }
                                                />)
                                            }
                                        </Carousel>

                                    </CardBody>
                                </Card>
                                <div className="grid grid-col grid-cols-1" >
                                    <div className="shadow-md p-2 flex justify-between items-center"><span><LocalParkingIcon fontSize="small" color="primary" /></span><span className="uppercase">Free Parking</span><span className="uppercase">{selectedRoomToView.free_parking}</span></div>
                                    <div className="shadow-md p-2 flex justify-between items-center"><span><NotInterestedIcon fontSize="small" color="primary" /></span><span className="uppercase">Free Cancellation</span><span className="uppercase">{selectedRoomToView.free_cancellation}</span></div>
                                    <div className="shadow-md p-2 flex justify-between items-center"><span><WifiIcon fontSize="small" color="primary" /></span><span className="uppercase">Free Wifi</span><span className="uppercase">{selectedRoomToView.free_wifi}</span></div>
                                    <div className="shadow-md p-2 flex justify-between items-center"><span><BreakfastDining fontSize="small" color="primary" /></span><span className="uppercase">Free Breakfast</span><span className="uppercase">{selectedRoomToView.free_breakfast}</span></div>
                                    <div className="shadow-md p-2 flex justify-between items-center"><span>{selectedRoomToView.occupancy === 2 ? <KingBedIcon fontSize="small" color="primary" /> : <SingleBedIcon fontSize="small" color="primary" />}</span><span className="uppercase">Occupancy</span><span>{selectedRoomToView.occupancy === 2 ? "DOUBLE" : "SINGLE"}</span></div>


                                </div>
                                <div className="shadow-md p-2">
                                <p>
                                {selectedRoomToView.description}
                                
                                </p>
                                </div>
                          
                            </ModalBody>
                            <ModalFooter>
                                <Button color="danger" variant="flat" onPress={() => setshowRoomDetailsModal(null)}>
                                    Cancel
                                </Button>

                            </ModalFooter>



                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
